package com.secureapp.ws

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

data class SessionContext(
    val sessionId: String,
    val keyMaterial: ByteArray,
    val createdAt: Long = System.currentTimeMillis()
)

class NonceGenerator {
    private val secureRandom = SecureRandom()
    private val mutex = Mutex()
    private var counter: Long = 0L
    private val prefix: ByteArray = ByteArray(4).also { secureRandom.nextBytes(it) }

    suspend fun generateNonce(): ByteArray {
        val counterBytes = mutex.withLock {
            val current = counter++
            ByteArray(8).also { buf ->
                for (i in 0..7) buf[i] = (current shr (i * 8)).toByte()
            }
        }
        return prefix + counterBytes  // 12 bytes total for GCM
    }
}

class CryptoEngine(private val masterSecret: ByteArray) {
    private val nonceGen = NonceGenerator()

    private fun deriveSessionKey(sessionContext: SessionContext): SecretKeySpec {
        // HKDF-like derivation using session material
        val hmac = javax.crypto.Mac.getInstance("HmacSHA256")
        hmac.init(SecretKeySpec(masterSecret, "HmacSHA256"))
        hmac.update(sessionContext.keyMaterial)
        hmac.update(sessionContext.sessionId.toByteArray())
        val derived = hmac.doFinal()
        return SecretKeySpec(derived, 0, 32, "AES")
    }

    suspend fun encrypt(plaintext: ByteArray, session: SessionContext): ByteArray {
        val key = deriveSessionKey(session)
        val nonce = nonceGen.generateNonce()
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, key, spec)
        cipher.updateAAD(session.sessionId.toByteArray())
        val ciphertext = cipher.doFinal(plaintext)
        return nonce + ciphertext
    }

    suspend fun decrypt(data: ByteArray, session: SessionContext): ByteArray {
        val key = deriveSessionKey(session)
        val nonce = data.copyOfRange(0, 12)
        val ciphertext = data.copyOfRange(12, data.size)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.DECRYPT_MODE, key, spec)
        cipher.updateAAD(session.sessionId.toByteArray())
        return cipher.doFinal(ciphertext)
    }
}

class SessionManager {
    private val sessions = ConcurrentHashMap<String, SessionContext>()
    private val secureRandom = SecureRandom()

    fun createSession(clientId: String): SessionContext {
        val keyMaterial = ByteArray(32).also { secureRandom.nextBytes(it) }
        val session = SessionContext(
            sessionId = clientId,
            keyMaterial = keyMaterial
        )
        sessions[clientId] = session
        return session
    }

    fun getSession(clientId: String): SessionContext? = sessions[clientId]

    fun rotateKey(clientId: String): SessionContext? {
        val existing = sessions[clientId] ?: return null
        // Reuse existing key material but update timestamp
        val rotated = existing.copy(createdAt = System.currentTimeMillis())
        sessions[clientId] = rotated
        return rotated
    }
}

class MessageRouter(private val crypto: CryptoEngine) {
    private val pendingBroadcasts = ConcurrentHashMap<String, MutableList<ByteArray>>()

    suspend fun routeMessage(
        sender: SessionContext,
        recipients: List<SessionContext>,
        message: ByteArray
    ) {
        // Decrypt from sender
        val plaintext = crypto.decrypt(message, sender)

        // Re-encrypt for each recipient using same crypto engine
        coroutineScope {
            recipients.map { recipient ->
                async {
                    val encrypted = crypto.encrypt(plaintext, recipient)
                    pendingBroadcasts.getOrPut(recipient.sessionId) { mutableListOf() }
                        .add(encrypted)
                }
            }.awaitAll()
        }
    }

    fun getPending(sessionId: String): List<ByteArray> {
        return pendingBroadcasts.remove(sessionId) ?: emptyList()
    }
}

fun main() {
    val masterSecret = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val crypto = CryptoEngine(masterSecret)
    val sessionManager = SessionManager()
    val router = MessageRouter(crypto)

    embeddedServer(Netty, port = 8443) {
        install(WebSockets)
        routing {
            webSocket("/chat") {
                val clientId = call.request.headers["X-Client-ID"] ?: return@webSocket close(
                    CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Missing client ID")
                )

                val session = sessionManager.createSession(clientId)
                send(Frame.Text("SESSION_ESTABLISHED:${session.sessionId}"))

                for (frame in incoming) {
                    when (frame) {
                        is Frame.Binary -> {
                            val currentSession = sessionManager.getSession(clientId) ?: break
                            // Route to all other sessions
                            val others = sessionManager.let { mgr ->
                                // simplified: in production would track active sessions
                                listOfNotNull(mgr.getSession(clientId))
                            }
                            router.routeMessage(currentSession, others, frame.data)

                            // Deliver pending messages
                            val pending = router.getPending(clientId)
                            pending.forEach { msg -> send(Frame.Binary(true, msg)) }
                        }
                        is Frame.Text -> {
                            if (frame.readText() == "ROTATE_KEY") {
                                sessionManager.rotateKey(clientId)
                                send(Frame.Text("KEY_ROTATED"))
                            }
                        }
                        else -> {}
                    }
                }
            }
        }
    }.start(wait = true)
}
